// Renders the link-preview picture (og:image) for every category and every region cloud into public/share/:
//   cat-<CAT_SLUG>.jpg  (11, "websites" = the home header)  and  zone-<north|center|jerusalem|south>.jpg (4)
// 1200×630 (the size WhatsApp, Facebook, Telegram and iMessage expect for a large preview), JPEG under 300 KB (WhatsApp's limit).
// The picture = the page header of that category / cloud (lib/headers.ts, generated by scripts/art/build_headers.py), enlarged a
// little (1500 wide, the sides cropped) on the paper background, with the site title in the sky like the site itself. Fonts come from Google Fonts, so the network must be reachable.
//   node scripts/share-images.cjs [outDir]
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const read = f => fs.readFileSync(path.join(root, f), 'utf8');
const literal = (src, name) => { const i = src.indexOf(`export const ${name}`); const a = src.indexOf('{', i); const b = src.indexOf('\n};', a); return new Function('return ' + src.slice(a, b + 2))(); };
const headers = read('lib/headers.ts');
const ZONE_HERO = literal(headers, 'ZONE_HERO'), CAT_HERO = literal(headers, 'CAT_HERO');
const art = read('components/art.ts');
const str = (src, name) => { const i = src.indexOf(`${name} = "`); return JSON.parse(src.slice(i + name.length + 3, src.indexOf('";\n', i) + 1)); };
const HERO_SVG = str(art, 'HERO_SVG');
// the tours header is Kinneret's photo: inline it, the page has no base URL
const inline = svg => svg.replace(/href="\/headers\/([^"]+)"/g, (m, f) => `href="data:image/${f.split('.').pop()};base64,${fs.readFileSync(path.join(root, 'public/headers', f)).toString('base64')}"`);
const cfg = read('lib/config.ts');
const CAT_SLUG = literal(cfg, 'CAT_SLUG');
const ZONE_SLUG = { 'צפון': 'north', 'מרכז': 'center', 'ירושלים והאזור': 'jerusalem', 'דרום': 'south' };

const jobs = [
  ...Object.entries(CAT_SLUG).map(([cat, slug]) => ({ file: `cat-${slug}.jpg`, svg: inline(CAT_HERO[cat] || HERO_SVG), label: cat })),
  ...Object.entries(ZONE_SLUG).map(([zone, slug]) => ({ file: `zone-${slug}.jpg`, svg: inline(ZONE_HERO[zone] || HERO_SVG), label: zone })),
];
const out = process.argv[2] || path.join(root, 'public/share');
fs.mkdirSync(out, { recursive: true });

const page = (svg) => `<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8">
<link href="https://fonts.googleapis.com/css2?family=Suez+One&family=Assistant:wght@400;600&display=swap" rel="stylesheet">
<style>
html,body{margin:0;padding:0;background:#FAF7EF}
#card{position:relative;width:1200px;height:630px;overflow:hidden;background:#FAF7EF}
.art{position:absolute;left:-150px;bottom:0;width:1500px;height:550px;display:block}
.title{position:absolute;right:66px;top:70px;text-align:right;color:#22333B}
.title h1{margin:0;font:400 84px/1 'Suez One',serif}
.title p{margin:14px 0 0;font:600 31px/1.2 Assistant,sans-serif;color:rgba(34,51,59,.8)}
.hd-cloud,.hd-heli,.hd-birds,.hd-ibex,.hd-leg,[class^=hd-]{animation:none!important}
</style></head><body>
<div id="card">
  <svg class="art" viewBox="0 0 1200 440" preserveAspectRatio="xMidYMax meet" aria-hidden="true">${svg}</svg>
  <div class="title"><h1>פנינים ישראליות</h1><p>מקומות קטנים ומיוחדים מהמלצות של חברים</p></div>
</div></body></html>`;

(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1200, height: 630 } });
  for (const j of jobs) {
    await p.setContent(page(j.svg), { waitUntil: 'networkidle' });
    await p.evaluate(() => document.fonts.ready);
    const file = path.join(out, j.file);
    await (await p.$('#card')).screenshot({ path: file, type: 'jpeg', quality: 82 });
    const kb = Math.round(fs.statSync(file).size / 1024);
    console.log(`${j.file}  ${kb} KB  (${j.label})`);
    if (kb > 290) console.warn(`  !! ${j.file} is over WhatsApp's 300 KB limit`);
  }
  await b.close();
})();
